// Per design/stories/tower/005-accounts-roles-and-permissions.md and ADR
// 0017 (account/identity/role model). `identifiedBy: 'accountId'` --
// `accountId` is generated by the caller (node-flakes, see
// `src/lib/ids.ts`) at identity-resolution time; no `POST /accounts` route
// exists (Story 005) since accounts are only ever created via login
// resolution (`POST /identities/resolve`) or, later, invite acceptance
// that resolves through the same path.
//
// `grantedRoles`/`trialRoles` are opaque `{ name, scope }` pairs -- tower
// never interprets what a role name means (ADR 0069); it only stores,
// filters by scope, and reports them. Role *grant/revoke* command handlers
// are deliberately idempotent, defensive, set-membership operations (ADR
// 0038's ordering-defense requirement for the entitlement consumer, which
// is this actor's primary external writer besides invite redemption) --
// the command handlers themselves are thin pass-throughs; the *event*
// handlers do the idempotent merge, so replaying the same event twice
// (redelivery) or out of order is always safe.
export interface RoleGrant {
  name: string
  scope: 'tenant' | { application: string }
}

export interface UsageRecord {
  application: string
  meter: string
  periodUsage: number
  periodLimit: number | null
}

export interface AccountState {
  accountId: string
  tenant: string
  contactId: string
  status: 'active' | 'suspended' | 'deleted'
  emailVerified: boolean
  grantedRoles: RoleGrant[]
  trialRoles: RoleGrant[]
  trialExpiresAt: string | null
  permissions: unknown[]
  usage: UsageRecord[]
  createdAt: string
}

interface CreateCommand {
  accountId: string
  tenant: string
  contactId: string
}

interface GrantRoleCommand {
  role: RoleGrant
}

interface RevokeRoleCommand {
  role: RoleGrant
}

interface GrantTrialRoleCommand {
  role: RoleGrant
  trialExpiresAt: string
}

interface UpdateUsageCommand {
  application: string
  meter: string
  periodUsage: number
  periodLimit: number | null
}

interface ChangeEmailCommand {
  contactId: string
}

function sameRole(a: RoleGrant, b: RoleGrant): boolean {
  const scopeA = typeof a.scope === 'string' ? a.scope : `application:${a.scope.application}`
  const scopeB = typeof b.scope === 'string' ? b.scope : `application:${b.scope.application}`
  return a.name === b.name && scopeA === scopeB
}

function create(_account: AccountState, command: CreateCommand) {
  return {
    type: 'account.created',
    accountId: command.accountId,
    tenant: command.tenant,
    contactId: command.contactId,
  }
}

function grantRole(_account: AccountState, command: GrantRoleCommand) {
  return { type: 'account.role-granted', role: command.role }
}

function revokeRole(_account: AccountState, command: RevokeRoleCommand) {
  return { type: 'account.role-revoked', role: command.role }
}

function grantTrialRole(_account: AccountState, command: GrantTrialRoleCommand) {
  return { type: 'account.trial-role-granted', role: command.role, trialExpiresAt: command.trialExpiresAt }
}

// ADR 0076: repoints `account.contactId` to a new (or reused) contact
// record -- `contact.email` itself is immutable by design (ADR 0023), an
// email "change" is always a repoint, never an in-place edit. The route
// handler (routes/accounts.ts) is responsible for actually resolving
// `command.contactId` via `contactStore.upsert` *before* this command
// runs -- this actor only ever records the repoint, never computes the
// hash itself (no signet pepper access at this layer).
function changeEmail(_account: AccountState, command: ChangeEmailCommand) {
  return { type: 'account.contact-changed', contactId: command.contactId }
}

function updateUsage(_account: AccountState, command: UpdateUsageCommand) {
  return {
    type: 'account.usage-updated',
    application: command.application,
    meter: command.meter,
    periodUsage: command.periodUsage,
    periodLimit: command.periodLimit,
  }
}

function isActive(account: AccountState) {
  return account.status === 'active'
}

function suspend() {
  return { type: 'account.suspended' }
}

function rejectSuspend() {
  return Promise.reject(new Error('account must be active to be suspended'))
}

function created(account: AccountState, event: CreateCommand) {
  account.accountId = event.accountId
  account.tenant = event.tenant
  account.contactId = event.contactId
  account.status = 'active'
  account.emailVerified = false
  account.grantedRoles = []
  account.trialRoles = []
  account.trialExpiresAt = null
  account.permissions = []
  account.usage = []
  account.createdAt = new Date(0).toISOString() // replaced by consequent's own event timestamp on read
}

// Idempotent: a redelivered/duplicate `role-granted` event for a role
// already present is a silent no-op, never a duplicate array entry.
function roleGranted(account: AccountState, event: { role: RoleGrant }) {
  if (account.grantedRoles.some((r) => sameRole(r, event.role))) return
  account.grantedRoles = [...account.grantedRoles, event.role]
}

// Idempotent + tolerant of reordering: removes the role from *both*
// grantedRoles and trialRoles (a revoke doesn't need to know which list a
// prior grant landed the role in), and is a no-op if the role is already
// absent (e.g. a redelivered revoke arriving after another revoke already
// processed it).
function roleRevoked(account: AccountState, event: { role: RoleGrant }) {
  account.grantedRoles = account.grantedRoles.filter((r) => !sameRole(r, event.role))
  account.trialRoles = account.trialRoles.filter((r) => !sameRole(r, event.role))
}

function trialRoleGranted(account: AccountState, event: { role: RoleGrant, trialExpiresAt: string }) {
  if (!account.trialRoles.some((r) => sameRole(r, event.role))) {
    account.trialRoles = [...account.trialRoles, event.role]
  }
  // Defensive against out-of-order redelivery: a later (further-future)
  // expiry never regresses to an earlier one that arrives after it.
  if (!account.trialExpiresAt || new Date(event.trialExpiresAt) > new Date(account.trialExpiresAt)) {
    account.trialExpiresAt = event.trialExpiresAt
  }
}

function usageUpdated(account: AccountState, event: UpdateUsageCommand) {
  const idx = account.usage.findIndex((u) => u.application === event.application && u.meter === event.meter)
  const record = {
    application: event.application,
    meter: event.meter,
    periodUsage: event.periodUsage,
    periodLimit: event.periodLimit,
  }
  if (idx === -1) {
    account.usage = [...account.usage, record]
  } else {
    account.usage = account.usage.map((u, i) => (i === idx ? record : u))
  }
}

function suspended(account: AccountState) {
  account.status = 'suspended'
}

// Naturally idempotent -- redelivering the same `contact-changed` event
// (or the route naturally resolving to the same reused `contactId` on a
// retried request) just re-sets the same value, not a duplicate-effect
// bug the way an array-append event handler would need to guard against.
function contactChanged(account: AccountState, event: { contactId: string }) {
  account.contactId = event.contactId
}

export default function accountActor() {
  return {
    actor: {
      namespace: 'tower',
      type: 'account',
      identifiedBy: 'accountId',
      searchableBy: ['tenant', 'contactId', 'status'],
    },
    state: {
      accountId: '',
      tenant: '',
      contactId: '',
      status: 'active',
      emailVerified: false,
      grantedRoles: [],
      trialRoles: [],
      trialExpiresAt: null,
      permissions: [],
      usage: [],
      createdAt: '',
    },
    commands: {
      create,
      'grant-role': grantRole,
      'revoke-role': revokeRole,
      'grant-trial-role': grantTrialRole,
      'update-usage': updateUsage,
      'change-email': changeEmail,
      suspend: [
        { when: isActive, then: suspend },
        rejectSuspend,
      ],
    },
    events: {
      created,
      'role-granted': roleGranted,
      'role-revoked': roleRevoked,
      'trial-role-granted': trialRoleGranted,
      'usage-updated': usageUpdated,
      'contact-changed': contactChanged,
      suspended,
    },
  }
}
